def suma_pares(lista):
    if not lista:
        return 0
    return (lista[0] if lista[0] % 2 == 0 else 0) + suma_pares(lista[1:])

def agrupar_por_curso(inscripciones):
    grupos = {}
    for alumno, curso in inscripciones:
        grupos.setdefault(curso, []).append(alumno)
    for alumnos in grupos.values():
        alumnos.sort()
    return grupos

def nota_valida(texto):
    try:
        nota = int(texto)
    except ValueError:
        raise ValueError("no es un número")
    if not 0 <= nota <= 20:
        raise ValueError("fuera de rango")
    return nota
